4	import {
5		WITNESS_DOWNLOAD_CAPTURE_RULE,
6		WITNESS_FILE_INPUT_LOAD_RULE,
7		WITNESS_NON_LOOPBACK_QUERY_FREE_PATH_RULE,
8	} from './witness-real-app.ts';
9	import type {
10		WitnessConsoleErrorInventory,
11		WitnessConsoleErrorInventoryEntry,
12		WitnessDownloadCaptureInventory,
13		WitnessFailedRequestInventory,
14		WitnessFailedRequestInventoryEntry,
15		WitnessFileInputLoadInventory,
16		WitnessFileInputSurfaceEntry,
17		WitnessMeasuredScrollAbsence,
18		WitnessMockedNonLoopbackSeamEntry,
19		WitnessMockedNonLoopbackSeamInventory,
