25	export const WITNESS_ANGULAR_TINY_TRANSLATOR_SCHEMA =
26		'versionless.witness-angular-tiny-translator.v1' as const;
27	export const WITNESS_ANGULAR_TINY_TRANSLATOR_RECEIPT_PATH =
28		'evidence/runs/witness-angular-tiny-translator/receipt.json' as const;
29	export const ANGULAR_TINY_TRANSLATOR_FIXTURE = 'angular-tiny-translator-v0-12-0' as const;
30	export const ANGULAR_TINY_TRANSLATOR_APP = 'angular-tiny-translator' as const;
