32	/**
33	 * The immutable TinyTranslator source identity, bound here so the browser proof
34	 * cannot silently rebind itself to a different revision or archive.
35	 *
36	 * The pin is a lightweight tag — no tag object, no tagger, no signature — so the
37	 * ref is recorded alongside what actually carries the identity: the commit sha,
38	 * the root tree sha and the archive digest. Saying which of them the identity
39	 * rests on is the point of recording all four.
40	 */
41	export const ANGULAR_TINY_TRANSLATOR_SOURCE = Object.freeze({
42		repository: 'https://github.com/martinroob/tiny-translator',
43		ref: 'refs/tags/v0.12.0',
44		tagKind: 'lightweight — no tag object, no tagger and no signature; the commit is unsigned',
45		revision: '08dcacf6a41d5a6f6dfbc71d858adcdc4c85691a',
46		rootTreeSha: 'ba39de904e28030dcc8a09e28bbd1b0db7247bb7',
47		archiveSha256: '424209463bcccca1714d520e2f68c55d54b204c69367bbeefcdf930d01d3ac18',
48		archiveBytes: 186861,
49		frontendRoot: '.',
50		license: 'MIT',
51		licenseSha256: 'b33e2f180e3d22c42c1511895a448e9aafb848a51a43a9cfae163f19f7288fb9',
52	});
53	
54	/**
55	 * The two build-lane receipts this browser proof stands on, each bound by the
56	 * digest it declares for itself and by the sha256 of its exact bytes, so the
57	 * proof cannot be re-pointed at a rebuilt or edited build receipt.
58	 *
59	 * Each entry also names the ONE output root the browser proof is allowed to
60	 * serve for that lane, and the sibling build whose byte-identity is what makes
61	 * that root canonical rather than merely most recent: each lane built twice
62	 * into a cleaned directory and emitted the same inventory, file for file and
63	 * digest for digest. Serving `rebuild-1` or `dist-7` is therefore serving the
64	 * lane, not one arbitrary build of it, and the verifier below re-reads the
65	 * byte-identity claim out of the bound receipt rather than trusting this list.
66	 */
67	export const ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS = Object.freeze([
68		Object.freeze({
69			lane: 'baseline',
70			path: 'evidence/runs/angular-tiny-translator-v0-12-0/u17-era-baseline.json',
71			schemaVersion: 'versionless.angular-tiny-translator-era-baseline.v1',
72			digest: 'f996cc39a4b24f30782591e967ddf02fe8448a950db71015ff9f9d214f8c23b6',
73			sha256: '43ba7cbea92a931566d44bb74e0006a7e541f5f77e8ee589d6814aaa48ab17c5',
74			canonicalRoot: 'dist/rebuild-1',
75			repeatedRoot: 'dist/rebuild-2',
76			files: 524,
77			byteIdenticalSibling: true,
78		}),
79		Object.freeze({
80			lane: 'migrated',
81			path: 'evidence/runs/angular-tiny-translator-v0-12-0/u17d-final-green-lane.json',
82			schemaVersion: 'versionless.angular-tiny-translator-final-lane.v1',
83			digest: '88be4807ed80b6f7a4e7238e42c94aa88d8aa1b01603aca74902166f2345ca45',
84			sha256: '60d3631b7e0e49797a22ed9e05135672475165fdcf4649f3da9c914af7726291',
85			canonicalRoot: 'dist-7',
86			repeatedRoot: 'dist-8',
87			files: 524,
88			byteIdenticalSibling: true,
89		}),
90	]);
