92	/**
93	 * The seam this application reaches for outside loopback in the ERA lane,
94	 * pinned query-free by the standing rule.
95	 *
96	 * `src/index.html` links the Material Icons stylesheet unconditionally, so every
97	 * document load of the era build requests it. The harness answers it inside the
98	 * browser context: nothing leaves the machine, and the request is still written
99	 * down, because a seam that is answered is still a seam the application has.
100	 */
101	export const WITNESS_ANGULAR_TINY_TRANSLATOR_BASELINE_SEAMS = Object.freeze([
102		Object.freeze({ method: 'GET', path: 'https://fonts.googleapis.com/icon' }),
103	]) as readonly WitnessMockedNonLoopbackSeamEntry[];
104	
105	/**
106	 * The migrated lane's seams are pinned by ORIGIN rather than by full path, and
107	 * the reason is worth stating plainly rather than hiding in a looser check.
108	 *
109	 * The Angular 16 builder inlines the Google Fonts stylesheet into the document
110	 * at build time, so the migrated build never asks `fonts.googleapis.com` for
111	 * anything at run time; what it asks for instead is the font file the inlined
112	 * `@font-face` rule points at, on `fonts.gstatic.com`, under a path the font
113	 * provider itself mints and versions. That path is a fact about the provider's
114	 * CDN on the day the build ran, not a fact about this migration, and inventing
115	 * one here would be a pin nobody measured. So the schema pins what the
116	 * migration decides — that every migrated seam is a `fonts.gstatic.com` GET and
117	 * that no migrated seam is on `fonts.googleapis.com` at all — and the published
118	 * receipt pins the exact member, identically across all four runs.
119	 */
120	export const WITNESS_ANGULAR_TINY_TRANSLATOR_SEAM_ORIGINS = Object.freeze({
121		baseline: 'https://fonts.googleapis.com',
122		migrated: 'https://fonts.gstatic.com',
123	});
124	
125	/**
126	 * The divergence between the two lanes' seams, recorded as a declared
127	 * difference rather than normalized away.
128	 *
129	 * It is a genuine, observable change across the migration: the era build asks
130	 * the network for a stylesheet at run time, and the migrated build already has
131	 * that stylesheet in its document and asks only for the font. Both are answered
132	 * in-context, neither leaves the machine, and neither lane ends up with the
133	 * glyphs — which is what the two icon degradations below record.
134	 */
135	export const WITNESS_ANGULAR_TINY_TRANSLATOR_FONT_SEAM_DIFFERENCE = Object.freeze({
136		state: 'recorded-behavioral-migration-difference',
137		baseline: 'requests-the-icon-stylesheet-from-fonts-googleapis-com-at-runtime',
138		migrated:
139			'ships-the-stylesheet-inlined-by-the-builder-and-requests-only-the-font-from-fonts-gstatic-com',
140		cause: 'the Angular 16 builder inlines Google Fonts into the document at build time and emits a preconnect for the font host; the era Angular CLI 1.5 builder emitted the stylesheet link untouched',
141		answeredInContext: true,
142		successfulNonLoopbackInEitherLane: 0,
143		masked: false,
144	});
145	
146	/**
147	 * The two distinct ways `mat-icon` degrades with the font seam answered
148	 * in-context, one per lane. Both lanes render ligature text instead of glyphs,
149	 * and they arrive there differently:
150	 *
151	 * - the era build never receives the stylesheet, so no `@font-face` rule and no
152	 *   `Material Icons` family ever reach the page at all;
153	 * - the migrated build already carries the inlined rule, so the family IS
154	 *   declared and applied — and the font file behind it is the thing that never
155	 *   arrives.
156	 *
157	 * Recording them as one degradation would erase a real difference between the
158	 * lanes, so each is asserted separately and the difference between them is
159	 * declared. The measured resolved family is carried in the run, and it has to
160	 * agree with the lane's `iconFontFamilyDeclared` flag.
161	 */
162	export const WITNESS_ANGULAR_TINY_TRANSLATOR_MAT_ICON_DEGRADATIONS = Object.freeze({
163		baseline: Object.freeze({
164			state: 'measured-icon-degradation',
165			cause: 'icon-stylesheet-answered-in-context-so-no-font-face-rule-reaches-the-page',
166			iconFontFamilyDeclared: false,
167			rendersLigatureText: true,
168			masked: false,
169		}),
170		migrated: Object.freeze({
171			state: 'measured-icon-degradation',
172			cause: 'stylesheet-inlined-at-build-time-and-its-font-file-answered-in-context',
173			iconFontFamilyDeclared: true,
174			rendersLigatureText: true,
175			masked: false,
176		}),
177	});
178	
179	/** The family name the inlined rule declares, matched against the measurement. */
180	export const WITNESS_ANGULAR_TINY_TRANSLATOR_ICON_FONT_FAMILY = 'Material Icons' as const;
181	
182	/**
183	 * The closed list of rendered-appearance probes the journey measures, identical
184	 * in both lanes so the two measurements are comparable at all.
185	 *
186	 * Selectors are element- and attribute-based on purpose: Angular Material's own
187	 * class names were rewritten onto MDC between 5.0.0-rc.2 and 16.2, and a probe
188	 * pinned to a class name would be measuring the framework's naming rather than
189	 * the application's appearance.
190	 */
191	export const WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_PROBES = Object.freeze([
192		Object.freeze({
193			label: 'application-toolbar',
194			selector: 'mat-toolbar',
195			properties: Object.freeze(['background-color', 'color']),
196		}),
197		Object.freeze({
198			label: 'material-icon',
199			selector: 'mat-icon',
200			properties: Object.freeze(['font-family', 'font-size']),
201		}),
202		Object.freeze({
203			label: 'raised-button',
204			selector: 'button[mat-raised-button]',
205			properties: Object.freeze(['background-color', 'border-radius', 'font-family']),
206		}),
207		Object.freeze({
208			label: 'document-body',
209			selector: 'body',
210			properties: Object.freeze(['background-color', 'margin-top']),
211		}),
212	]);
213	
214	/**
215	 * The probes whose resolved values are allowed to differ across the eleven-major
216	 * lift, each with the reason it differs. This is a declaration, not an
217	 * allowance, and it is checked in both directions: a probe outside this list
218	 * that differs fails the run, and a probe inside it that does NOT differ fails
219	 * too — a declared difference that stopped being real is a stale claim, and
220	 * leaving it standing would let the receipt describe a migration that no longer
221	 * happened.
222	 */
223	export const WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_DIFFERENCES = Object.freeze([
224		Object.freeze({
225			label: 'material-icon',
226			why: 'the two lanes degrade differently: the era lane never receives a Material Icons rule, and the migrated lane applies the inlined one whose font never arrives',
227		}),
228		Object.freeze({
229			label: 'raised-button',
230			why: 'Angular Material reimplemented the raised button on MDC between 5.0.0-rc.2 and 16.2, so the shipped shape and type ramp are different by construction rather than by regression',
231		}),
232	]);
233	
234	/**
235	 * The application's routing shape, pinned instead of a route sequence.
236	 *
237	 * The router runs with `useHash: true`, so every navigation is a fragment. What
238	 * a browser proof can be held to here is that each recorded route is a hash
239	 * route naming one of the application's own declared routes, in the same
240	 * sequence in every lane and pass — and that is what is checked. A pinned
241	 * sequence belongs to the journey that drives it, and this unit drives none.
242	 */
243	export const WITNESS_ANGULAR_TINY_TRANSLATOR_ROUTE_SHAPE = Object.freeze({
244		router: 'angular-router-use-hash',
245		prefix: '#/',
246		known: Object.freeze([
247			'/autotranslatesummary',
248			'/configureautotranslate',
249			'/createproject',
250			'/editproject',
251			'/home',
252			'/selectfilter',
253			'/translate',
254		]),
255	});
256	
257	/**
258	 * The file-input surface the application declares, and the exact synthetic
259	 * fixture the harness is allowed to load into it.
260	 *
261	 * The fixture is authored for this proof and contains no third party's content:
262	 * a translation file's units are the application's data, and a real one would
263	 * put somebody else's strings into published evidence. It is bound by byte
264	 * length and digest here, so a journey cannot quietly load a different file
265	 * than the one this schema declares.
266	 */
267	export const WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES = Object.freeze([
268		Object.freeze({
269			label: 'translation-file',
270			selector: 'input[type=file]',
271			fixturePath: 'fixtures/angular-tiny-translator-v0-12-0/witness/synthetic-messages.xlf',
272		}),
273	]) as readonly WitnessFileInputSurfaceEntry[];
274	
275	/** The synthetic fixture's exact identity, bound so the load cannot drift. */
276	export const WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE = Object.freeze({
277		fileName: 'synthetic-messages.xlf',
278		format: 'XLIFF 1.2',
279		transUnits: 3,
280		bytes: 1079,
281		sha256: '9740ca22119d02d660c8ad595be9bb5de4a33bef9473f5a0e5a11da6c53d2284',
282	});
283	
284	/**
285	 * The download surface the application declares. TinyTranslator's export is a
286	 * client-side download through its own downloader service — the file is built
287	 * in the browser and handed to the browser, and nothing is uploaded anywhere.
288	 * The context accepts downloads only because this declaration exists.
289	 */
290	export const WITNESS_ANGULAR_TINY_TRANSLATOR_DOWNLOAD_SURFACE = Object.freeze({
291		state: 'declared-client-side-download',
292		produced: 'the applications own downloader service, client-side, through file-saver',
293		uploaded: false,
294		leftTheMachine: false,
295		expectedDownloads: 1,
296	});
297	
298	/**
299	 * The migration's accommodation framing.
300	 *
301	 * Zero manual migration steps is the claim, and the inventory that backs it is
302	 * not restated here: it is referenced in the bound migrated build receipt,
303	 * which itemises all nine changed application files and the five capabilities
304	 * that changed them. The journey obligation is the other half — the one
305	 * declared difference the build lanes could not observe, named so that the
306	 * browser proof is required to observe it rather than inherit it.
307	 */
308	export const WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS = Object.freeze({
309		manualMigrationSteps: 0,
310		inventory: Object.freeze({
311			record: 'evidence/runs/angular-tiny-translator-v0-12-0/u17d-final-green-lane.json',
312			applicationFilesChanged: 9,
313			capabilities: 5,
314			note: 'Every edit was made by a generic capability reading the installed closure or the compiler, and the nine files and five capabilities are itemised in the bound migrated build receipt rather than summarised here.',
315		}),
316		journeyObligations: Object.freeze([
317			'FileReader-service parity: the migrated lane inserted a `typeof` guard where `FileReader.result` is typed `string | ArrayBuffer`, and the build lane recorded as a declared difference that nothing it ran observed the guarded statements. The browser proof must load a translation file through the application own file input in BOTH lanes and assert the parse is identical, which is what turns that declared difference into an observed one.',
318		]),
319	});
