321	/** The per-lane assertion the icon degradation is recorded as, with its measurement. */
322	export type WitnessAngularTinyTranslatorMatIcon = {
323		state: 'measured-icon-degradation';
324		cause: string;
325		iconFontFamilyDeclared: boolean;
326		rendersLigatureText: true;
327		masked: false;
328		/** The family the browser actually resolved for the probed icon element. */
329		resolvedFontFamily: string;
330		/** The ligature text the icon rendered instead of a glyph. */
331		renderedText: string;
332	};
333	
334	/** The FileReader parity reading, identical in both lanes by obligation. */
335	export type WitnessAngularTinyTranslatorFileReaderParity = {
336		state: 'measured-identical-parse-across-lanes';
337		assertion: string;
338		parsedUnits: number;
339		parsedDigest: string;
340	};
341	
342	export type WitnessAngularTinyTranslatorPersistence = {
343		store: 'browser-local-storage';
344		service: 'the applications own BackendLocalStorageService behind BackendServiceAPI';
345		backend: 'none';
346		stubbed: false;
347		keysBeforeJourney: string[];
348		keysAfterJourney: string[];
349		survivesOnlineReload: true;
350	};
351	
352	export type WitnessAngularTinyTranslatorJourney = {
353		matIcon: WitnessAngularTinyTranslatorMatIcon;
354		fileReaderParity: WitnessAngularTinyTranslatorFileReaderParity;
355		persistence: WitnessAngularTinyTranslatorPersistence;
356	};
357	
358	export type WitnessAngularTinyTranslatorRun = WitnessRealAppRun & {
359		consoleErrorInventory: WitnessConsoleErrorInventory;
360		failedRequestInventory: WitnessFailedRequestInventory;
361		mockedNonLoopbackSeams: WitnessMockedNonLoopbackSeamInventory;
362		fileInputLoads: WitnessFileInputLoadInventory;
363		downloadCaptures: WitnessDownloadCaptureInventory;
364		renderedStyles: WitnessRenderedStyleEvidence;
365		applicationJourney: WitnessAngularTinyTranslatorJourney;
366		scrollAbsence: WitnessMeasuredScrollAbsence;
367		behaviorDigest: string;
368	};
369	
370	export type WitnessAngularTinyTranslatorMutation = {
371		failure: 'witness-semantic-assertion';
372		intendedFailure: true;
373		lane: 'migrated';
374		seam: string;
375		path: string;
376		offset: number;
377		beforeSha256: string;
378		mutatedSha256: string;
379		afterRestoreSha256: string;
380		restoredByteIdentically: true;
381		restoredRun: 'pass';
382		restoredBehaviorDigest: string;
383	};
384	
385	export type WitnessAngularTinyTranslatorReceipt = {
386		schemaVersion: typeof WITNESS_ANGULAR_TINY_TRANSLATOR_SCHEMA;
387		result: 'pass';
388		fixture: typeof ANGULAR_TINY_TRANSLATOR_FIXTURE;
389		source: typeof ANGULAR_TINY_TRANSLATOR_SOURCE;
390		provenance: Record<string, unknown>;
391		canonicalReceipts: Array<{
392			lane: 'baseline' | 'migrated';
393			path: string;
394			schemaVersion: string;
395			digest: string;
396			sha256: string;
397			canonicalRoot: string;
398			repeatedRoot: string;
399			files: number;
400			byteIdenticalSibling: true;
401		}>;
402		runs: WitnessAngularTinyTranslatorRun[];
403		mutation: WitnessAngularTinyTranslatorMutation;
404		consoleErrors: Readonly<
405			Record<'baseline' | 'migrated', readonly WitnessConsoleErrorInventoryEntry[]>
406		>;
407		failedRequests: Readonly<
408			Record<'baseline' | 'migrated', readonly WitnessFailedRequestInventoryEntry[]>
409		>;
410		/**
411		 * The exact per-lane seam membership as published. The baseline half is the
412		 * pinned constant; the migrated half is the exact member the runs observed,
413		 * held to the declared origin rule and required to be identical in every run.
414		 */
415		mockedSeams: Record<'baseline' | 'migrated', WitnessMockedNonLoopbackSeamEntry[]>;
416		fontSeamDifference: typeof WITNESS_ANGULAR_TINY_TRANSLATOR_FONT_SEAM_DIFFERENCE;
417		matIconDegradations: Record<'baseline' | 'migrated', WitnessAngularTinyTranslatorMatIcon>;
418		renderedStyleParity: {
419			state: 'measured-resolved-styles-with-declared-differences';
420			probes: number;
421			declaredDifferences: typeof WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_DIFFERENCES;
422			otherProbesAgree: true;
423		};
424		fileInput: {
425			surfaces: readonly WitnessFileInputSurfaceEntry[];
426			fixture: typeof WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE;
427			rule: typeof WITNESS_FILE_INPUT_LOAD_RULE;
428		};
429		downloads: {
430			surface: typeof WITNESS_ANGULAR_TINY_TRANSLATOR_DOWNLOAD_SURFACE;
431			rule: typeof WITNESS_DOWNLOAD_CAPTURE_RULE;
432			/** Per run, the downloads that run read back. */
433			captured: Array<{
434				lane: 'baseline' | 'migrated';
435				pass: 1 | 2;
436				files: Array<{ suggestedFilename: string; bytes: number; sha256: string }>;
437			}>;
438		};
439		persistence: {
440			store: 'browser-local-storage';
441			backend: 'none';
442			stubbed: false;
443			survivesOnlineReload: true;
444		};
445		routeShape: typeof WITNESS_ANGULAR_TINY_TRANSLATOR_ROUTE_SHAPE;
446		scrollAbsence: WitnessMeasuredScrollAbsence;
447		accommodations: typeof WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS;
448		readiness: {
449			angularLineage: { ready: 1; total: 4; counted: false };
450			overall: { ready: 3; total: 12 };
451		};
452		locality: {
453			mode: 'offline';
454			successfulNonLoopback: 0;
455			osWideIsolation: false;
456			mockedNonLoopbackSeams: number;
457		};
458		nonclaims: string[];
459		integrity: { algorithm: 'sha256'; canonicalDigest: string };
460	};
461	
462	const exact = (left: unknown, right: unknown): boolean =>
463		canonicalize(left) === canonicalize(right);
464	
465	const sha256Digest = (value: unknown): boolean => typeof value === 'string' && value.length === 64;
466	
467	export function witnessAngularTinyTranslatorRawDigest(
468		run: WitnessAngularTinyTranslatorRun | WitnessRealAppRun,
469	): string {
470		const { pass: _pass, result: _result, semanticDigest: _semanticDigest, ...raw } = run;
471		const withoutBehavior = { ...raw } as Record<string, unknown>;
472		delete withoutBehavior.behaviorDigest;
473		return sha256(canonicalize(withoutBehavior));
474	}
475	
476	/** The probe labels whose values are allowed to differ between the lanes. */
477	function declaredDifferenceLabels(): string[] {
478		return WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_DIFFERENCES.map((entry) => entry.label);
479	}
480	
481	/**
482	 * The rendered-style projection that participates in the parity digest: the
483	 * probes the lanes must agree on, in full, plus the LABELS of the ones they are
484	 * declared to disagree on. Folding the declared-difference values in would make
485	 * the two lanes disagree about a difference the receipt already records;
486	 * dropping the labels would let a probe leave the declaration unnoticed.
487	 */
488	function renderedStyleProjection(evidence: WitnessRenderedStyleEvidence | undefined): unknown {
489		const differing = new Set(declaredDifferenceLabels());
490		return {
491			state: evidence?.state,
492			agreeing: (evidence?.probes ?? []).filter((probe) => !differing.has(probe.label)),
493			declaredDifferenceLabels: (evidence?.probes ?? [])
494				.map((probe) => probe.label)
495				.filter((label) => differing.has(label)),
496		};
497	}
498	
499	/**
500	 * Lane-independent behavior projection.
501	 *
502	 * Production bytes are lane-specific by construction — eleven majors of bundler
503	 * apart — so the byte inventory stays in the run and out of this digest. So do
504	 * the three things this migration genuinely changed: the font seam, the icon
505	 * degradation and the two declared style differences. Each of them is verified
506	 * exactly against its own pinned per-lane record elsewhere, and what is left
507	 * here is everything the two lanes must agree on, including the file the page
508	 * was handed, the file the page produced, and what the store settled to.
509	 */
510	export function witnessAngularTinyTranslatorBehaviorDigest(
511		run: WitnessAngularTinyTranslatorRun | WitnessRealAppRun,
512	): string {
513		const journey = (run as WitnessAngularTinyTranslatorRun).applicationJourney as
514			| WitnessAngularTinyTranslatorJourney
515			| undefined;
516		const seams = run.mockedNonLoopbackSeams;
517		return sha256(
