871	export function parseWitnessAngularTinyTranslatorReceipt(
872		value: unknown,
873	): WitnessAngularTinyTranslatorReceipt {
874		if (value === null || typeof value !== 'object' || Array.isArray(value))
875			throw new Error('Angular TinyTranslator Witness receipt must be an object');
876		const receipt = value as WitnessAngularTinyTranslatorReceipt;
877		const expectedRuns = new Set(['baseline:1', 'baseline:2', 'migrated:1', 'migrated:2']);
878		const behaviors = new Set<string>();
879		if (
880			receipt.schemaVersion !== WITNESS_ANGULAR_TINY_TRANSLATOR_SCHEMA ||
881			receipt.result !== 'pass' ||
882			receipt.fixture !== ANGULAR_TINY_TRANSLATOR_FIXTURE ||
883			!exact(receipt.source, ANGULAR_TINY_TRANSLATOR_SOURCE) ||
884			!Array.isArray(receipt.canonicalReceipts) ||
885			!exact(receipt.canonicalReceipts, ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS) ||
886			!Array.isArray(receipt.runs) ||
887			receipt.runs.length !== 4
888		)
889			throw new Error('Angular TinyTranslator Witness binding differs');
890		for (const run of receipt.runs) {
891			const key = `${run.lane}:${run.pass}`;
892			if (
893				!expectedRuns.delete(key) ||
894				run.app !== ANGULAR_TINY_TRANSLATOR_APP ||
895				run.framework !== 'angular' ||
896				run.result !== 'pass' ||
897				run.cleanPage !== true ||
898				run.successfulNonLoopback !== 0 ||
899				run.witnessRecord.pageErrors !== 0 ||
900				run.witnessRecord.consoleErrors !== run.consoleErrorInventory?.total ||
901				run.witnessRecord.failedRequests !== run.failedRequestInventory?.total ||
902				run.offlineEvidence.state !== 'not-applicable' ||
903				run.observerFinalization.workerEvents.length !== 0 ||
904				run.servedStatic.byteIdentical !== true ||
905				run.scrollSurface !== undefined ||
906				run.interactions.length === 0 ||
907				run.semanticDigest !== witnessAngularTinyTranslatorRawDigest(run) ||
908				run.behaviorDigest !== witnessAngularTinyTranslatorBehaviorDigest(run)
909			)
910				throw new Error(`Angular TinyTranslator Witness run differs: ${key}`);
911			assertRouteShape(run.routes, key);
912			assertConsoleErrorInventory(
913				run.consoleErrorInventory,
914				receipt.consoleErrors?.[run.lane] ?? [],
915				key,
916			);
917			assertFailedRequestInventory(
918				run.failedRequestInventory,
919				receipt.failedRequests?.[run.lane] ?? [],
920				key,
921			);
922			assertMockedSeams(
923				run.mockedNonLoopbackSeams,
924				run.lane,
925				receipt.mockedSeams?.[run.lane] ?? [],
926				key,
927			);
928			assertFileInputLoads(run.fileInputLoads, key);
929			assertDownloadCaptures(run.downloadCaptures, key);
930			assertRenderedStyles(run.renderedStyles, key);
931			assertMatIcon(run.applicationJourney, run.lane, key);
932			assertFileReaderParity(run.applicationJourney, key);
933			assertPersistence(run.applicationJourney, key);
934			assertScrollAbsence(run.scrollAbsence, key);
935			behaviors.add(run.behaviorDigest);
