940			throw new Error('Angular TinyTranslator Witness lane pair is incomplete');
941		assertRenderedStyleDifferences(baseline.renderedStyles.probes, migrated.renderedStyles.probes);
942		assertScrollAbsence(receipt.scrollAbsence, 'receipt');
943		if (
944			expectedRuns.size !== 0 ||
945			behaviors.size !== 1 ||
946			!exact(receipt.mockedSeams?.baseline, WITNESS_ANGULAR_TINY_TRANSLATOR_BASELINE_SEAMS) ||
947			exact(receipt.mockedSeams.baseline, receipt.mockedSeams.migrated) ||
948			!exact(receipt.fontSeamDifference, WITNESS_ANGULAR_TINY_TRANSLATOR_FONT_SEAM_DIFFERENCE) ||
949			!exact(receipt.matIconDegradations?.baseline, baseline.applicationJourney.matIcon) ||
950			!exact(receipt.matIconDegradations.migrated, migrated.applicationJourney.matIcon) ||
951			receipt.renderedStyleParity?.state !==
952				'measured-resolved-styles-with-declared-differences' ||
953			receipt.renderedStyleParity.probes !==
954				WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_PROBES.length ||
955			receipt.renderedStyleParity.otherProbesAgree !== true ||
956			!exact(
957				receipt.renderedStyleParity.declaredDifferences,
958				WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_DIFFERENCES,
959			) ||
960			!exact(receipt.fileInput?.surfaces, WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES) ||
961			!exact(receipt.fileInput.fixture, WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE) ||
962			receipt.fileInput.rule !== WITNESS_FILE_INPUT_LOAD_RULE ||
963			!exact(receipt.downloads?.surface, WITNESS_ANGULAR_TINY_TRANSLATOR_DOWNLOAD_SURFACE) ||
964			receipt.downloads.rule !== WITNESS_DOWNLOAD_CAPTURE_RULE ||
965			receipt.downloads.captured.length !== receipt.runs.length ||
966			receipt.downloads.captured.some((entry, index) => {
967				const run = receipt.runs[index];
968				return (
969					run === undefined ||
970					entry.lane !== run.lane ||
971					entry.pass !== run.pass ||
972					!exact(entry.files, run.downloadCaptures.captured)
