977				backend: 'none',
978				stubbed: false,
979				survivesOnlineReload: true,
980			}) ||
981			!exact(receipt.routeShape, WITNESS_ANGULAR_TINY_TRANSLATOR_ROUTE_SHAPE) ||
982			!exact(receipt.accommodations, WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS) ||
983			receipt.mutation?.intendedFailure !== true ||
984			receipt.mutation.failure !== 'witness-semantic-assertion' ||
985			receipt.mutation.lane !== 'migrated' ||
986			receipt.mutation.seam.length === 0 ||
987			receipt.mutation.restoredByteIdentically !== true ||
988			receipt.mutation.restoredRun !== 'pass' ||
989			receipt.mutation.beforeSha256 !== receipt.mutation.afterRestoreSha256 ||
990			receipt.mutation.beforeSha256 === receipt.mutation.mutatedSha256 ||
991			!behaviors.has(receipt.mutation.restoredBehaviorDigest) ||
992			!exact(receipt.readiness, {
