1014				(bound) =>
1015					`${bound.lane} \`${bound.path}\` (${bound.digest.slice(0, 12)}) served from \`${bound.canonicalRoot}\`, byte-identical to \`${bound.repeatedRoot}\` across ${bound.files} files`,
