1021			`${lane}: ${receipt.matIconDegradations[lane].cause}, resolved family \`${receipt.matIconDegradations[lane].resolvedFontFamily}\`, rendered \`${receipt.matIconDegradations[lane].renderedText}\``;
1022		const differences = receipt.renderedStyleParity.declaredDifferences
1023			.map((entry) => `\`${entry.label}\` — ${entry.why}`)
1024			.join('; ');
1025		const downloads = receipt.downloads.captured
1026			.map(
1027				(entry) =>
1028					`${entry.lane} pass ${entry.pass}: ${entry.files
1029						.map((file) => `\`${file.suggestedFilename}\` ${file.bytes} bytes`)
1030						.join(', ')}`,
1031			)
1032			.join(' | ');
1033		return `# TinyTranslator v0.12.0 — direct Witness browser proof
1034	
1035	- Result: pass
1036	- Canonical SHA-256: ${receipt.integrity.canonicalDigest}
1037	- Runs: 2 baseline + 2 migrated production-static browser journeys
1038	- Behavioral parity: ${receipt.runs[0]!.behaviorDigest}
1039	- Bound build lanes: ${lanes}
1040	- Migration: Angular 5.0.3 to Angular 16.2 — eleven majors, the longest lift in the corpus — at ${receipt.accommodations.manualMigrationSteps} manual migration steps; the ${receipt.accommodations.inventory.applicationFilesChanged} changed application files and ${receipt.accommodations.inventory.capabilities} capabilities that changed them are itemised in \`${receipt.accommodations.inventory.record}\`
1041	- Journey obligation carried into this proof: ${receipt.accommodations.journeyObligations.join(' ')}
1042	- File handed to the page: \`${receipt.fileInput.fixture.fileName}\` (${receipt.fileInput.fixture.format}, ${receipt.fileInput.fixture.transUnits} units, ${receipt.fileInput.fixture.bytes} bytes, sha256 ${receipt.fileInput.fixture.sha256.slice(0, 12)}), through the one declared surface. ${receipt.fileInput.rule}
1043	- Files the page produced: ${downloads}. ${receipt.downloads.rule}
1044	- Mocked non-loopback seams (answered in-context, none left the machine) — baseline: ${seams('baseline')}; migrated: ${seams('migrated')}
1045	- Recorded font-seam difference: ${receipt.fontSeamDifference.cause}; masked: ${String(receipt.fontSeamDifference.masked)}
1046	- Icon degradation, measured per lane — ${icon('baseline')}; ${icon('migrated')}
1047	- Rendered appearance: ${receipt.renderedStyleParity.probes} probes measured off the live page in both lanes; every probe outside the declared differences resolves identically. Declared differences: ${differences}
1048	- Persistence: ${receipt.persistence.store}, backend ${receipt.persistence.backend}, stubbed: ${String(receipt.persistence.stubbed)}, survives an online reload: ${String(receipt.persistence.survivesOnlineReload)}
1049	- Routing: ${receipt.routeShape.router}; every recorded route is a \`${receipt.routeShape.prefix}\` route naming one of the application's own ${receipt.routeShape.known.length} declared routes
1050	- Mutation proof: \`${receipt.mutation.seam}\` in \`${receipt.mutation.path}\` at offset ${receipt.mutation.offset} made the journey red, byte-identical restoration made it green again
1051	- Scroll: ${receipt.scrollAbsence.state} — ${receipt.scrollAbsence.documentOverflow}
1052	- Angular lineage readiness: unchanged at ${receipt.readiness.angularLineage.ready}/${receipt.readiness.angularLineage.total}; this vertical is not counted
1053	
1054	${receipt.nonclaims.map((claim) => `- ${claim}`).join('\n')}
1055	`;
1056	}
1057	
1058	export function witnessAngularTinyTranslatorAggregateMember(digestValue: string) {
1059		return {
1060			id: 'witness-angular-tiny-translator',
1061			framework: 'angular',
1062			track: 'production-readiness-direct-witness-angular5-to-angular16-browser-builder',
1063			bundler: 'angular-cli-1.5.4-webpack-3.8.1-to-angular-16.2-browser-builder',
1064			runtime: 'node-8.9.3-to-node-16.20.2',
1065			result: 'pass',
1066			receipt: WITNESS_ANGULAR_TINY_TRANSLATOR_RECEIPT_PATH,
1067			digest: digestValue,
1068		};
1069	}
1070	
1071	/**
1072	 * Re-reads each bound build receipt and checks the byte-identity this proof
1073	 * rests on out of the receipt itself rather than out of the list above: the era
1074	 * lane declares `byteStable`, the migrated lane declares an identical repeated
1075	 * build, and each must cover the file count the canonical root was served with.
1076	 */
1077	function assertBoundBuildReceipt(
1078		bound: WitnessAngularTinyTranslatorReceipt['canonicalReceipts'][number],
1079		parsed: Record<string, unknown>,
1080	): void {
1081		if (parsed.schemaVersion !== bound.schemaVersion || parsed.digest !== bound.digest)
1082			throw new Error(
1083				`Angular TinyTranslator bound build receipt identity differs: ${bound.path}`,
1084			);
1085		if (bound.lane === 'baseline') {
1086			const inventory = parsed.inventory;
1087			if (
1088				parsed.byteStable !== true ||
1089				!Array.isArray(inventory) ||
1090				inventory.length !== bound.files
1091			)
1092				throw new Error(`Angular TinyTranslator era lane byte-identity differs: ${bound.path}`);
1093			return;
1094		}
1095		const determinism = parsed.determinism as { identical?: unknown; files?: unknown } | undefined;
1096		if (determinism?.identical !== true || determinism.files !== bound.files)
1097			throw new Error(
1098				`Angular TinyTranslator migrated lane byte-identity differs: ${bound.path}`,
1099			);
1100	}
1101	
1102	export async function verifyWitnessAngularTinyTranslatorEvidence(rootDir = '.') {
1103		const root = resolve(rootDir);
1104		const receiptPath = join(root, WITNESS_ANGULAR_TINY_TRANSLATOR_RECEIPT_PATH);
1105		const receipt = parseWitnessAngularTinyTranslatorReceipt(
1106			JSON.parse(await readFile(receiptPath, 'utf8')),
1107		);
1108		for (const bound of receipt.canonicalReceipts) {
1109			const bytes = await readFile(join(root, bound.path));
1110			if (sha256(bytes) !== bound.sha256)
1111				throw new Error(
1112					`Angular TinyTranslator bound build receipt bytes drifted: ${bound.path}`,
1113				);
1114			assertBoundBuildReceipt(
1115				bound,
1116				JSON.parse(bytes.toString('utf8')) as Record<string, unknown>,
1117			);
1118		}
1119		const fixture = await readFile(
1120			join(root, WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES[0]!.fixturePath),
1121		);
1122		if (
1123			sha256(fixture) !== WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE.sha256 ||
1124			fixture.length !== WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE.bytes
1125		)
1126			throw new Error('Angular TinyTranslator synthetic file-input fixture drifted');
1127		if (
1128			(await readFile(join(dirname(receiptPath), 'receipt.md'), 'utf8')) !==
1129			renderWitnessAngularTinyTranslatorReceipt(receipt)
1130		)
1131			throw new Error('Angular TinyTranslator human Witness receipt differs');
1132		return {
1133			valid: true as const,
1134			digest: receipt.integrity.canonicalDigest,
1135			artifacts: 0,
1136			receipt,
1137		};
1138	}
1139

