1	import { access, cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
2	import { basename, dirname, join, relative, resolve } from 'pathe';
3	import { canonicalize, sha256 } from '../../../core/src/receipts/canonicalize.ts';
4	import {
5		WITNESS_CANCELLED_DUPLICATE_FETCH_NON_LOOPBACK_SCOPE,
6		WITNESS_CANCELLED_DUPLICATE_FETCH_RULE,
7		WITNESS_NON_LOOPBACK_QUERY_FREE_PATH_RULE,
8	} from '../../../core/src/receipts/witness-real-app.ts';
9	import {
10		ANGULAR_JIRA_CLONE_CANONICAL_RECEIPTS,
11		ANGULAR_JIRA_CLONE_FIXTURE,
12		ANGULAR_JIRA_CLONE_SOURCE,
13		parseWitnessAngularJiraCloneReceipt,
14		renderWitnessAngularJiraCloneReceipt,
15		WITNESS_ANGULAR_JIRA_CLONE_CANCELLED_DUPLICATE_FETCHES,
16		WITNESS_ANGULAR_JIRA_CLONE_CONSOLE_ERRORS,
17		WITNESS_ANGULAR_JIRA_CLONE_FAILED_REQUESTS,
18		WITNESS_ANGULAR_JIRA_CLONE_MOCKED_SEAMS,
19		WITNESS_ANGULAR_JIRA_CLONE_SCHEMA,
20		WITNESS_ANGULAR_JIRA_CLONE_SERVICE_WORKER,
21		witnessAngularJiraCloneBehaviorDigest,
22		witnessAngularJiraCloneDigest,
23		witnessAngularJiraCloneRawDigest,
24		type WitnessAngularJiraCloneMutation,
25		type WitnessAngularJiraCloneReceipt,
26		type WitnessAngularJiraCloneRun,
27	} from '../../../core/src/receipts/witness-angular-jira-clone.ts';
28	import { executeAngularJiraCloneWitnessRun, JIRA_CLONE_MUTATION_SEAM } from './real-app-run.ts';
29	import { verifyLinkedWitnessProvenance } from './provenance.ts';
30	
31	const root = resolve(import.meta.dirname, '../../../..');
32	const fixtureEvidence = join(root, 'evidence/runs/angular-jira-clone');
33	const witnessEvidence = join(root, 'evidence/runs/witness-angular-jira-clone');
34	const stageRoot = join(root, '.versionless/stage/witness-angular-jira-clone');
35	/**
36	 * The two committed build lanes: the era baseline rebuilt on its own Angular
37	 * 13.2 custom-webpack cell, and the migrated Angular 16.2 browser-builder
38	 * output. Both are produced offline by
39	 * `packages/cli/src/fixture/angular-jira-clone-build-lanes-run.ts` and are
40	 * bound to this proof by the four receipts the schema pins.
41	 */
42	const sourceOutputs = {
43		baseline: join(root, '.versionless/cache/angular-jira-clone-baseline/rebuild/dist-1'),
44		migrated: join(root, '.versionless/stage/angular-jira-clone-mj2/dist-a'),
45	} as const;
46	const laneFileCounts = { baseline: 24, migrated: 24 } as const;
47	
48	async function exists(path: string): Promise<boolean> {
49		return access(path).then(
50			() => true,
51			() => false,
52		);
53	}
54	
55	async function files(directory: string): Promise<string[]> {
56		const output: string[] = [];
57		for (const entry of await readdir(directory, { withFileTypes: true })) {
58			const path = join(directory, entry.name);
59			if (entry.isDirectory()) output.push(...(await files(path)));
60			else if (entry.isFile()) output.push(path);
61		}
62		return output.sort();
63	}
64	
65	async function stageInputs(): Promise<Record<'baseline' | 'migrated', string>> {
66		const lanes = join(stageRoot, 'lanes');
67		await rm(lanes, { recursive: true, force: true });
68		const staged = { baseline: join(lanes, 'baseline'), migrated: join(lanes, 'migrated') };
69		for (const lane of ['baseline', 'migrated'] as const) {
70			if (!(await exists(sourceOutputs[lane])))
71				throw new Error(`jira-clone ${lane} production output is absent`);
72			await mkdir(dirname(staged[lane]), { recursive: true });
73			await cp(sourceOutputs[lane], staged[lane], { recursive: true, force: false });
74			const stagedFiles = await files(staged[lane]);
75			if (stagedFiles.length !== laneFileCounts[lane])
76				throw new Error(
77					`jira-clone ${lane} lane file count differs: ${stagedFiles.length} against ${laneFileCounts[lane]}`,
78				);
79		}
80		return staged;
81	}
82	
83	async function executeRuns(
84		lanes: Record<'baseline' | 'migrated', string>,
85	): Promise<WitnessAngularJiraCloneRun[]> {
86		const runs: WitnessAngularJiraCloneRun[] = [];
87		for (const lane of ['baseline', 'migrated'] as const)
88			for (const pass of [1, 2] as const) {
89				const raw = await executeAngularJiraCloneWitnessRun({
90					lane,
91					pass,
92					laneRoot: lanes[lane],
93					receiptRoot: join(stageRoot, 'receipts'),
94				});
95				const run = raw as WitnessAngularJiraCloneRun;
96				if (run.semanticDigest !== witnessAngularJiraCloneRawDigest(run))
97					throw new Error(`jira-clone ${lane} pass ${pass} raw digest differs`);
98				runs.push({ ...run, behaviorDigest: witnessAngularJiraCloneBehaviorDigest(run) });
99			}
100		if (new Set(runs.map((run) => run.behaviorDigest)).size !== 1)
101			throw new Error('jira-clone baseline/migrated behavior parity differs');
102		return runs;
103	}
104	
105	/**
106	 * Byte mutation on the migrated build.
107	 *
108	 * The seam is the status the board reports for the column the drag moves the
109	 * issue into. It was chosen because it is load-bearing three times over: it is
110	 * a string a reader sees, the journey asserts it exactly off the reopened issue
111	 * modal, and it is the settled Akita state rather than the drop animation. The
112	 * uniqueness demanded here is the same discipline the corpus uses everywhere —
113	 * exactly one served module may carry it, exactly once — so overwriting it in
114	 * place cannot be absorbed by a second copy somewhere else in the bundle.
115	 */
116	async function semanticMutation(
117		laneRoot: string,
118		behaviorDigest: string,
119	): Promise<WitnessAngularJiraCloneMutation> {
120		const expected = Buffer.from(JIRA_CLONE_MUTATION_SEAM);
121		const candidates: Array<{ path: string; offset: number }> = [];
122		for (const path of await files(laneRoot)) {
123			const bytes = await readFile(path);
124			const offset = bytes.indexOf(expected);
125			if (offset < 0) continue;
126			if (bytes.lastIndexOf(expected) !== offset)
127				throw new Error('jira-clone semantic seam is not unique within its file');
128			candidates.push({ path, offset });
129		}
130		const target = candidates[0];
131		if (candidates.length !== 1 || target === undefined || !target.path.endsWith('.js'))
132			throw new Error('jira-clone semantic seam is not a single served module');
133		const before = await readFile(target.path);
134		const mutated = Buffer.from(before);
135		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
136		const beforeSha256 = sha256(before);
137		const mutatedSha256 = sha256(mutated);
138		let intendedFailure = false;
139		try {
140			await writeFile(target.path, mutated);
141			try {
142				await executeAngularJiraCloneWitnessRun({
143					lane: 'migrated',
144					pass: 1,
145					laneRoot,
146					receiptRoot: join(stageRoot, 'mutation-receipt'),
147				});
148			} catch (error) {
149				const message = error instanceof Error ? error.message : String(error);
150				intendedFailure = message.includes(JIRA_CLONE_MUTATION_SEAM);
151			}
152		} finally {
153			await writeFile(target.path, before);
154		}
155		const afterRestoreSha256 = sha256(await readFile(target.path));
156		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
157			throw new Error('jira-clone semantic mutation was not exact red and byte-restored');
158		const restored = (await executeAngularJiraCloneWitnessRun({
159			lane: 'migrated',
160			pass: 1,
161			laneRoot,
162			receiptRoot: join(stageRoot, 'restoration-receipt'),
163		})) as WitnessAngularJiraCloneRun;
164		const restoredBehaviorDigest = witnessAngularJiraCloneBehaviorDigest(restored);
165		if (restoredBehaviorDigest !== behaviorDigest)
166			throw new Error('jira-clone restored browser behavior differs');
167		return {
168			failure: 'witness-semantic-assertion',
169			intendedFailure: true,
170			lane: 'migrated',
171			seam: JIRA_CLONE_MUTATION_SEAM,
172			path: relative(laneRoot, target.path),
173			offset: target.offset,
174			beforeSha256,
175			mutatedSha256,
176			afterRestoreSha256,
177			restoredByteIdentically: true,
178			restoredRun: 'pass',
179			restoredBehaviorDigest,
180		};
181	}
182	
183	async function bindCanonicalReceipts(): Promise<
184		WitnessAngularJiraCloneReceipt['canonicalReceipts']
185	> {
186		return await Promise.all(
187			ANGULAR_JIRA_CLONE_CANONICAL_RECEIPTS.map(async (pinned) => {
188				const bytes = await readFile(join(root, pinned.path));
189				const value = JSON.parse(bytes.toString('utf8')) as {
190					schemaVersion?: unknown;
191					digest?: unknown;
192				};
193				if (
194					value.schemaVersion !== pinned.schemaVersion ||
195					value.digest !== pinned.digest ||
196					sha256(bytes) !== pinned.sha256
197				)
198					throw new Error(`jira-clone bound build receipt identity differs: ${pinned.path}`);
199				return {
200					path: pinned.path,
201					schemaVersion: pinned.schemaVersion,
202					digest: pinned.digest,
203					sha256: pinned.sha256,
204				};
205			}),
206		);
207	}
208	
209	/**
210	 * The tracked-event counts every run must agree on, taken from the first run
211	 * and required of the rest. The behavior digest already carries them, so this
212	 * is a second, louder statement of the same fact rather than a new one.
213	 */
214	function trackedEvents(runs: readonly WitnessAngularJiraCloneRun[]): Record<string, number> {
215		const first = runs[0]?.witnessRecord.trackedEventCounts;
216		if (first === undefined) throw new Error('jira-clone published no runs to summarize');
217		for (const run of runs)
218			if (canonicalize(run.witnessRecord.trackedEventCounts) !== canonicalize(first))
219				throw new Error('jira-clone tracked-event counts differ between runs');
220		return first;
221	}
222	
223	export async function runWitnessAngularJiraClone(): Promise<WitnessAngularJiraCloneReceipt> {
224		if (
225			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
226			process.env.NPM_CONFIG_OFFLINE !== 'true'
227		)
228			throw new Error('jira-clone Witness requires dual offline controls');
229		if (await exists(witnessEvidence)) throw new Error('jira-clone Witness output collision');
230		const provenance = await verifyLinkedWitnessProvenance(root);
231		const canonicalReceipts = await bindCanonicalReceipts();
232		const lanes = await stageInputs();
233		const runs = await executeRuns(lanes);
234		const mutation = await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest);
235		const artifacts = join(fixtureEvidence, 'artifacts');
236		await mkdir(artifacts, { recursive: true });
237		await writeFile(join(artifacts, 'witness-journeys.json'), `${canonicalize(runs)}\n`, {
238			flag: 'wx',
239		});
240		await writeFile(join(artifacts, 'witness-mutation.json'), `${canonicalize(mutation)}\n`, {
241			flag: 'wx',
242		});
243		const receipt: WitnessAngularJiraCloneReceipt = {
244			schemaVersion: WITNESS_ANGULAR_JIRA_CLONE_SCHEMA,
245			result: 'pass',
246			fixture: ANGULAR_JIRA_CLONE_FIXTURE,
247			source: ANGULAR_JIRA_CLONE_SOURCE,
248			provenance,
249			canonicalReceipts,
250			runs,
251			mutation,
252			serviceWorker: WITNESS_ANGULAR_JIRA_CLONE_SERVICE_WORKER,
253			consoleErrors: WITNESS_ANGULAR_JIRA_CLONE_CONSOLE_ERRORS,
254			failedRequests: WITNESS_ANGULAR_JIRA_CLONE_FAILED_REQUESTS,
255			mockedNonLoopbackSeams: {
256				category: WITNESS_ANGULAR_JIRA_CLONE_MOCKED_SEAMS,
257				pathPolicy: WITNESS_NON_LOOPBACK_QUERY_FREE_PATH_RULE,
258				instances: runs.map((run) => ({
259					lane: run.lane,
260					pass: run.pass,
261					observed: run.mockedNonLoopbackSeams.observed,
262					absent: run.mockedNonLoopbackSeams.absent,
263				})),
264			},
265			cancelledDuplicateFetches: {
266				category: WITNESS_ANGULAR_JIRA_CLONE_CANCELLED_DUPLICATE_FETCHES,
267				corroborationRule: WITNESS_CANCELLED_DUPLICATE_FETCH_RULE,
268				nonLoopbackScope: WITNESS_CANCELLED_DUPLICATE_FETCH_NON_LOOPBACK_SCOPE,
269				instances: runs.map((run) => ({
270					lane: run.lane,
271					pass: run.pass,
272					observed: run.cancelledDuplicateFetches.observed,
273					absent: run.cancelledDuplicateFetches.absent,
274					admitted: run.cancelledDuplicateFetches.admitted,
275				})),
276			},
277			renderedStyles: runs[0]!.renderedStyles,
278			trackedEvents: trackedEvents(runs),
279			scrollAbsence: runs[0]!.scrollAbsence,
280			buildLanes: {
281				baseline: {
282					angular: 'Angular 13.2',
283					builder: '@angular-builders/custom-webpack:browser over ./webpack.config.js',
284					node: 'node 16.20.2 (darwin-arm64, native)',
285					distFiles: laneFileCounts.baseline,
286				},
287				migrated: {
288					angular: 'Angular 16.2',
289					builder: '@angular-devkit/build-angular:browser',
290					node: 'node 16.20.2 (darwin-arm64, native)',
291					distFiles: laneFileCounts.migrated,
292				},
293			},
294			persistence: {
295				board: 'in-memory-store',
296				browserStorage: 'none-written',
297				backend: 'none',
298				stubbed: false,
299				survivesOnlineReload: false,
300			},
301			readiness: {
302				angularLineage: { ready: 1, total: 4, counted: false },
303				overall: { ready: 3, total: 12 },
304			},
305			locality: {
306				mode: 'offline',
307				successfulNonLoopback: 0,
308				mockedNonLoopbackSeams: WITNESS_ANGULAR_JIRA_CLONE_MOCKED_SEAMS.migrated.length,
309				osWideIsolation: false,
310			},
311			nonclaims: [
312				'This is one Angular lineage under direct Witness and does not establish generic Angular, Angular CLI, `@angular-builders/custom-webpack:browser`, or `@angular-devkit/build-angular:browser` support.',
313				'The Angular lineage readiness score is unchanged; this vertical is not counted before Judge audit.',
314				'The board is solved inside the browser by the application itself from the project document it bundles; no backend exists, nothing was stubbed or seeded by the harness, and no request left the loopback origin successfully.',
315				'Nothing the journey does survives a reload, and that is the recorded behavior rather than a limitation of the run: the application keeps the board in an in-memory store, writes no browser storage, and restores the seeded board on every load. The drag, the title edit and the created issue are all gone afterwards, and the journey measures that they are.',
316				'Editing the issue description is not claimed. It is a Quill surface that does not accept the synthetic keystrokes the driver produces, so what a claim would record is the harness’s own limitation rather than the application’s behavior; the journey asserts only that the seeded description renders.',
317				'Scroll is not claimed. Every stage of the journey was measured with the same generic viewport mechanism a scroll claim would use, and none of them produced a document taller than the 1280x720 viewport, because the application pins the document to the viewport and gives the board columns their own overflow.',
318				'Neither lane emits a single console error. That inventory is therefore empty, and empty is the strictest setting of that mechanism rather than a blanket allowance: any message at all lands outside the inventory and fails the run.',
319				'The exact failed-request inventory is empty in both lanes and every failed request still fails the run, with one named and corroborated exception that is a category rather than an allowance. The journey’s final gesture is an online reload, and the reload can tear down a page with an error-reporting envelope still in flight, which the browser cancels with `net::ERR_ABORTED`. Only that exact method, path and reason is in the category, it carries no count, and an instance is admitted only when the same page also delivered the same report successfully in the same run.',
320				'Every endpoint the application reaches for outside the bounded loopback origin is declared, and each one is answered by the harness inside the browser context, so none of them left the machine. The declared paths carry scheme, host and pathname only: the analytics measurement id and the error-reporting public key both live in the query, and the query is never recorded. Two of the ten are the animated images embedded in the seeded description of the issue the journey opens, fetched the moment the modal renders that description, which the journey asserts.',
321				'How many times a declared seam was requested is recorded per run as it was measured and is never pinned, and the two are not the same thing. The seam inventory is an accounting mechanism over endpoint identity: every declared endpoint must be observed or explicitly absent, nothing outside the inventory may be reached, and no request may succeed against a network. Repeat counts are load timing — the browser may reuse a response it already holds for an image the board renders more than once — so two passes of the same lane can legitimately record different counts for the same endpoint, and this receipt records what each pass actually did rather than a number the passes were made to agree on. What is required to agree, and does across every published pass, is the behavioral parity digest.',
322				'Neither build ships or registers a service worker. The browser context allowed registration and the application never attempted one, so the zero is the application’s own behavior rather than a policy imposed to produce it.',
323				'The two lanes emit different file names and different byte counts by construction, and the migration deliberately replaced the component library’s narrow style entry points with its single aggregate stylesheet. Byte parity across the lanes is not claimed here and is recorded separately by the bound build-parity receipt; what is claimed is that the seven rendered-appearance measurements are identical in both lanes.',
324				'Locality is process-scoped and does not establish operating-system-wide isolation.',
325				'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
326			],
327			integrity: { algorithm: 'sha256', canonicalDigest: '' },
328		};
329		receipt.integrity.canonicalDigest = witnessAngularJiraCloneDigest(receipt);
330		parseWitnessAngularJiraCloneReceipt(receipt);
331		await mkdir(witnessEvidence, { recursive: true });
332		const canonical = canonicalize(receipt);
333		/**
334		 * The companion is rendered from the receipt as published rather than from
335		 * the object in memory, and the difference is not cosmetic. Canonicalization
336		 * sorts object keys, so the tracked-event counts and the resolved style
337		 * properties come back in a different order than the browser reported them.
338		 * A companion rendered from the in-memory object would therefore disagree
339		 * with the same companion rendered from the file, and `verify` — which only
340		 * ever has the file — would be right to reject it. Rendering from the
341		 * round trip makes the human receipt a function of the bytes it accompanies.
342		 */
343		const published = parseWitnessAngularJiraCloneReceipt(JSON.parse(canonical));
344		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonical}\n`, { flag: 'wx' });
345		await writeFile(
346			join(witnessEvidence, 'receipt.md'),
347			renderWitnessAngularJiraCloneReceipt(published),
348			{ flag: 'wx' },
349		);
350		return published;
351	}
352	
353	export async function verifyWitnessAngularJiraClone(
354		output = witnessEvidence,
355	): Promise<WitnessAngularJiraCloneReceipt> {
356		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
357		const receipt = parseWitnessAngularJiraCloneReceipt(
358			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
359		);
360		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
361			throw new Error('jira-clone linked Witness provenance differs');
362		for (const bound of receipt.canonicalReceipts)
363			if (sha256(await readFile(join(root, bound.path))) !== bound.sha256)
364				throw new Error(`jira-clone bound build receipt bytes drifted: ${bound.path}`);
365		if (
366			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
367			renderWitnessAngularJiraCloneReceipt(receipt)
368		)
369			throw new Error('jira-clone human Witness receipt differs');
370		const serialized = canonicalize(receipt);
371		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
372			throw new Error('jira-clone receipt leaks host identity');
373		return receipt;
374	}
375	
376	export async function main(args = process.argv.slice(2)): Promise<void> {
377		const publishIndex = args.indexOf('--publish');
378		const verifyIndex = args.indexOf('--verify');
379		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
380			const output = resolve(root, args[publishIndex + 1]!);
381			if (output !== witnessEvidence) throw new Error('jira-clone publish path differs');
382			const receipt = await runWitnessAngularJiraClone();
383			process.stdout.write(
384				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
385			);
386			return;
387		}
388		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
389			const receipt = await verifyWitnessAngularJiraClone(resolve(root, args[verifyIndex + 1]!));
390			process.stdout.write(
391				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
392			);
393			return;
394		}
395		throw new Error('jira-clone Witness runner requires --run-twice --publish <dir> or --verify <dir>');
396	}
397	
398	if (basename(process.argv[1] ?? '') === 'angular-jira-clone-run.ts')
399		main().catch((error: unknown) => {
400			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
401			process.exitCode = 1;
402		});
403

