360	 * The exact rule that governs handing a file to a page, carried in the receipt
361	 * so a reader checks the rule rather than trusting the label.
362	 *
363	 * The mechanism is an opt-in and not a capability journeys may reach for: the
364	 * application declares the surface — the selector, and the fixture that is
365	 * loaded into it — and the harness loads exactly that. An application that
366	 * declares no file-input surface is run without the mechanism at all, so the
367	 * eleven verticals that never asked for it cannot have been changed by it.
368	 */
369	export const WITNESS_FILE_INPUT_LOAD_RULE =
370		'A file is handed to a page only through a surface the application itself declared, by selector and by fixture. The harness loads that fixture and no other, and records the bytes it handed over by file name, byte length and sha256. An application that declares no file-input surface has no way to load one.' as const;
371	
372	/**
373	 * The exact rule that governs reading back a file a page produced.
374	 *
375	 * Accepting downloads is a browser-context capability, and granting it to an
