   */
  isMasterXmbFileNeeded(): boolean {
    return this.isFileSelected() &&
      this.createdProject &&
      this.createdProject.translationFile &&
      this.createdProject.translationFile.fileType() === FILETYPE_XTB;
  }

  /**
   * Check, wether all needed is typed in.
